pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.SetLogFile(address(new LogFile()));
        c.Initialized();
    }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 amount3) public {
        // Restrict amounts to avoid overflow and keep them admissible
        amount1 = bound(amount1, 1, 100 ether);
        amount2 = bound(amount2, 1, 100 ether);
        amount3 = bound(amount3, 1, 100 ether);

        // Make three deposits from different EOAs with fuzzed amounts
        address alice = address(0x1000);
        address bob   = address(0x2000);
        address carol = address(0x3000);

        vm.deal(alice, amount1);
        vm.prank(alice);
        c.Deposit{value: amount1}();

        vm.deal(bob, amount2);
        vm.prank(bob);
        c.Deposit{value: amount2}();

        vm.deal(carol, amount3);
        vm.prank(carol);
        c.Deposit{value: amount3}();

        // Compute the sum of Val fields in LogFile.History
        LogFile log = LogFile(c.Log());
        uint256 loggedSum;
        for (uint256 i = 0; i < 3; i++) {
            ( , , uint256 v, ) = log.History(i);
            loggedSum += v;
        }

        // The contract's ether balance must equal the sum of logged values
        assertTrue(address(c).balance == loggedSum);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;

    Message LastMsg;

    function AddMessage(address _adr,uint _val,string memory _data)
    public
    {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

